    "correctIndex": 3,
    "hintEn": "Multiply and divide by the conjugate sqrt(x^2 + 2k) + x.",
    "hintAr": "اضرب واقسم على المرافق جذر(س^٢ + 2k) + س.",
    "stepByStepSolutionEn": [
      "1. Multiply by the conjugate:",
      "   $$x \\cdot \\frac{(\\sqrt{x^2 + 2} - x)(\\sqrt{x^2 + 2} + x)}{\\sqrt{x^2 + 2} + x} = \\frac{x(x^2 + 2 - x^2)}{\\sqrt{x^2 + 2} + x} = \\frac{2x}{\\sqrt{x^2 + 2} + x}$$",
      "2. Divide numerator and denominator by $x$:",
      "   $$\\lim_{x \\to +\\infty} \\frac{2}{\\sqrt{1 + \\frac{2}{x^2}} + 1} = \\frac{2}{1 + 1} = \\frac{2}{2} = 1$$"
    ],
    "stepByStepSolutionAr": [
      "١. الضرب في المرافق بسطاً ومقاماً:",
      "   $$x \\cdot \\frac{2}{\\sqrt{x^2 + 2} + x} = \\frac{2x}{\\sqrt{x^2 + 2} + x}$$",
      "٢. بقسمة حدي الكسر على $x$:",
      "   $$\\lim_{x \\to +\\infty} \\frac{2}{\\sqrt{1 + 0} + 1} = \\frac{2}{2} = 1$$"
    ],
    "teacherTipEn": "This classic limit demonstrates how sqrt(x^2 + 2k) - x ~ k/x as x -> infty.",
